using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    /// <summary>Fetches data from an external API endpoint and returns the JSON response.</summary>
    [McpServerTool, Description("Fetch data from an external API by path (e.g. \"/users/1\").")]
    public static async Task<string> FetchApiData(
        IHttpClientFactory httpClientFactory,
        [Description("The API path to call, e.g. /users/1")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("api");
        using var response = await client.GetAsync(path, cancellationToken);

        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizePrompt
{
    [McpServerPrompt, Description("Generate a concise summary of the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content
                {
                    Type = "text",
                    Text = $"""
                        Please summarize the following text in a {style} style.

                        Text:
                        {text}
                        """
                }
            }
        ];
    }
}

